actions.script:
const out = ec.service.sync().name('org.moqui.dev.DatabaseServices.count#TableRows').parameters({db, tableName: String(context.tableName || '')}).call() || {}
if (!ec.message.hasError()) ec.message.addMessage(ec.resource.expand('${tableName}: ${rowCount} rows', '', {tableName: out.tableName,
    rowCount: ec.l10n.format(Number(out.rowCount || 0), '#,##0')}), 'info')

const tableNames = [].concat(context.tableNames || []).map(String).filter(Boolean)
const out = ec.service.sync().name('org.moqui.dev.DatabaseServices.plan#TableMaintenance').parameters({db, tableNames,
    action: String(context.maintenance || ''), allowExclusiveLock: String(context.allowExclusiveLock) == 'true',
    description: 'Maintenance (' + String(context.maintenance || '') + ') of ' + tableNames.length + ' tables'}).call() || {}
planJobId = ec.message.hasError() ? null : out.jobId
// no job: nothing to run, or not allowed to run it; the statements are still what would run
if (!planJobId && !ec.message.hasError()) ec.message.addMessage(ec.resource.expand('Not planned as a job: ${reason} (${count} statements)', '',
    {reason: out.jobReason || 'nothing to run', count: (out.statements || []).length}), 'warning')
for (const warning of out.warnings || []) ec.message.addMessage(String(warning), 'warning')
